import multicastdns from 'multicast-dns';
import Homey = require('homey');

const SERVICE_TYPE = '_gridsense-homey._tcp.local';

export interface GridSenseGateway {
  instanceName: string; // volledige instance, bv. 'gridsense-1234abcd._gridsense-homey._tcp.local'
  name: string; // friendly: 'gridsense-1234abcd'
  ip: string;
  port: number;
  host: string;
  uuid: string | null;
  description: string | null;
  txt: Record<string, string | boolean>;
  lastSeen: number;
}

type MdnsInstance = ReturnType<typeof multicastdns>;

export default class GridSenseDiscovery {

  private homey: any;
  private mdns: MdnsInstance;
  private foundGateways = new Map<string, GridSenseGateway>();
  private readonly interval?: NodeJS.Timeout;

  constructor(homey: any) {
    this.homey = homey;

    this.mdns = multicastdns();

    this.mdns.on('response', (response) => {
      this.handleResponse(response);
    });

    // initiele query + periodiek refresher
    this.query();
    this.interval = this.homey.setInterval(() => this.query(), 10_000);
  }

  destroy() {
    if (this.interval) {
      this.homey.clearInterval(this.interval);
    }
    this.mdns.destroy();
  }

  private query() {
    this.mdns.query({
      questions: [
        {
          name: SERVICE_TYPE,
          type: 'PTR',
        },
      ],
    });
  }

  private handleResponse(response: any) {
    // combineer answers & additionals
    const records = [
      ...(response.answers ?? []),
      ...(response.additionals ?? []),
    ];

    const ptrRecords = records.filter(
      (rec) => rec.type === 'PTR' && rec.name === SERVICE_TYPE,
    );

    const now = Date.now();

    for (const ptr of ptrRecords) {
      const instanceName = String(ptr.data);

      const srv = records.find(
        (rec) => rec.type === 'SRV' && rec.name === instanceName,
      );
      if (!srv) continue;

      const txt = records.find(
        (rec) => rec.type === 'TXT' && rec.name === instanceName,
      );

      const host: string = srv.data.target;
      const aRecord = records.find((rec) => {
        return rec.type === 'A' && rec.name === host;
      });
      const aaaaRecord = records.find((rec) => {
        return rec.type === 'AAAA' && rec.name === host;
      });

      const discoveredRecord = aRecord || aaaaRecord;

      if (!discoveredRecord) {
        continue;
      }

      const ip: string = discoveredRecord.data;
      const { port } = srv.data;
      const txtData = txt ? this.parseTxt(txt.data) : {};

      const friendlyName = instanceName.replace(`.${SERVICE_TYPE}`, '');

      const gateway: GridSenseGateway = {
        instanceName,
        name: friendlyName,
        ip,
        port,
        host,
        uuid: (txtData.uuid as string) ?? null,
        description: (txtData.description as string) ?? null,
        txt: txtData,
        lastSeen: now,
      };

      this.foundGateways.set(instanceName, gateway);
    }
  }

  /**
   * TXT records → array van Buffer/string 'key=value'
   */
  private parseTxt(txtArray: Array<Buffer | string>): Record<string, string | boolean> {
    const obj: Record<string, string | boolean> = {};
    for (const item of txtArray) {
      const str = Buffer.isBuffer(item) ? item.toString('utf8') : String(item);
      if (!str) continue;

      const [k, v] = str.split('=');
      if (!k) continue;
      obj[k] = v !== undefined && v !== '' ? v : true;
    }
    return obj;
  }

  /**
   * Alleen gateways teruggeven die recent gezien zijn (default: laatste 60s)
   */
  getGateways(maxAgeMs = 60_000): GridSenseGateway[] {
    const now = Date.now();
    return Array.from(this.foundGateways.values()).filter(
      (g) => now - g.lastSeen <= maxAgeMs,
    );
  }

}

